library(strawr)

# Independent byte-level fixtures generated by straw/C++/tests/test_v10.py
# with trans=True, frag=True, and score=True for the second fixture.
for (name in c("trans-v10.hic", "trans-score-v10.hic")) {
    path <- system.file("extdata", name, package = "strawr")
    stopifnot(nzchar(path))
    for (resolution in c(10, 20)) {
        mean <- if (resolution == 10) 7 / 56 else 7 / 16
        product <- if (resolution == 10) 6 else 24
        for (norm in c("NONE", "VC")) {
            norm_product <- if (norm == "VC") product else 1
            for (matrix in c("oe", "expected")) {
                expected <- if (matrix == "expected") rep(mean, 3) else
                    c(1, 1, 5) / mean / norm_product
                for (reverse in c(FALSE, TRUE)) {
                    a <- if (reverse) "chrB" else "chrA"
                    b <- if (reverse) "chrA" else "chrB"
                    records <- straw(norm, path, a, b, "BP", resolution, matrix)
                    stopifnot(nrow(records) == 3, max(abs(records$counts - expected)) < 1e-5)
                }
            }
            window <- straw(norm, path, "chrB:0:10", "chrA:0:10", "BP", resolution, "oe")
            stopifnot(nrow(window) == 1,
                abs(window$counts[1] - 1 / mean / norm_product) < 1e-5)
        }
    }
    frag <- straw("NONE", path, "chrB", "chrA", "FRAG", 1, "oe")
    stopifnot(nrow(frag) == 3, abs(frag$counts[1] - 64 / 7) < 1e-5)
}
